SELECT DATE_TRUNC('MONTH', opened_date) AS opened_month, CASE WHEN sqft >= 15898 THEN 'high' WHEN sqft >= 3630 THEN 'mid' ELSE 'low' END AS sqft_bucket, MIN(sqft) AS min_sqft, COUNT(*) AS store_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) AS city_values FROM stores GROUP BY DATE_TRUNC('MONTH', opened_date), CASE WHEN sqft >= 15898 THEN 'high' WHEN sqft >= 3630 THEN 'mid' ELSE 'low' END ORDER BY city_values;
